import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for cross entropy loss
cross_entropy_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void cross_entropy_kernel(const float* predictions, const long* targets, float* loss, int batch_size, int num_classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float max_logit = predictions[idx * num_classes];
        for (int i = 1; i < num_classes; ++i) {
            if (predictions[idx * num_classes + i] > max_logit) {
                max_logit = predictions[idx * num_classes + i];
            }
        }

        float log_sum_exp = 0.0f;
        for (int i = 0; i < num_classes; ++i) {
            log_sum_exp += expf(predictions[idx * num_classes + i] - max_logit);
        }
        log_sum_exp = logf(log_sum_exp) + max_logit;

        int target = targets[idx];
        float log_prob = predictions[idx * num_classes + target] - log_sum_exp;
        loss[idx] = -log_prob;
    }
}

torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);
    auto loss = torch::zeros({batch_size}, predictions.options());

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    cross_entropy_kernel<<<num_blocks, block_size>>>(predictions.data_ptr<float>(), targets.data_ptr<long>(), loss.data_ptr<float>(), batch_size, num_classes);

    return loss.mean();
}
"""

cross_entropy_cpp_source = (
    "torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets);"
)

# Compile the inline CUDA code for cross entropy loss
cross_entropy = load_inline(
    name="cross_entropy",
    cpp_sources=cross_entropy_cpp_source,
    cuda_sources=cross_entropy_source,
    functions=["cross_entropy_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cross_entropy = cross_entropy

    def forward(self, predictions, targets):
        return self.cross_entropy.cross_entropy_cuda(predictions, targets)
